 CREATE TEMPORARY TABLE rrc233_recipes LIKE tradeskill_recipe;
 CREATE TEMPORARY TABLE rrc233_entries LIKE tradeskill_recipe_entries;
 CREATE TEMPORARY TABLE rrc233_items(id INT PRIMARY KEY,name VARCHAR(64) NOT NULL) ENGINE=InnoDB;
